/* From Uiverse.io by barisdogansutcu  - Tags: input, password, key */
.__UIV_SCOPE__ .password {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.__UIV_SCOPE__ .password input {
  width: 30px;
  height: 40px;
  text-align: center;
  background-color: transparent;
  border: none;
  border-bottom: solid 2px rgb(20, 181, 230);
  font-size: 20px;
  color: white;
  outline: none;
}
